create table stock_prod_order
(
    order_id          bigint auto_increment comment '主键'
        primary key,
    order_no          varchar(64)                     null comment '单据号',
    work_no           varchar(64)                     null comment '工令号',
    mat_code          varchar(64)                     null comment '物料编码',
    mat_name          varchar(128)                    null comment '物料名称',
    workshop_code     varchar(64)                     null comment '车间',
    route_code        varchar(30)                     null comment '工艺路线编码',
    quantity          decimal(24, 6) default 0.000000 null comment '数量',
    order_status      varchar(32)                     null comment '状态',
    del_flag          char           default '0'      null comment '删除标识',
    create_by         varchar(64)                     null comment '创建人',
    create_time       datetime                        null comment '创建时间',
    update_by         varchar(64)                     null comment '修改人',
    update_time       datetime                        null comment '修改时间',
    actual_quantity   decimal(24, 6) default 0.000000 null comment '实际完成数量',
    priority          tinyint        default 0        null comment '优先级（0普通 1紧急 2特急）',
    plan_start_date   datetime                        null comment '计划开始时间',
    plan_end_date     datetime                        null comment '计划完成时间',
    actual_start_date datetime                        null comment '实际开始时间',
    actual_end_date   datetime                        null comment '实际完成时间',
    equipment_code    varchar(30)                     null comment '生产设备编码',
    station_code      varchar(30)                     null comment '工位编码',
    customer_order_no varchar(30)                     null comment '关联客户订单号',
    plan_no           varchar(30)                     null comment '关联生产计划编号'
)
    comment '生产订单' collate = utf8mb4_general_ci
                       row_format = DYNAMIC;

